	kvPressureThresh := 0.8507  // @TUNE [0.85, 0.98] @TUNED(was=0.88, gain=+4.62, best_impact=avg_p95_ms:-12.0)
	cacheSessionBoost := 0.6114  // @TUNE [0.5, 4.0] @TUNED(was=3.5, gain=+4.62, best_impact=avg_p95_ms:-12.0)

